-- 114483: invocation-local dependency factoring for THREE Admin read RPCs.
-- No cache/GUC/temp state, no mutation RPC, no changed predecessor, no timeout override.
-- Every original expression survives; repeated STABLE reads use one MVCC statement snapshot.
-- Old RPCs remain intact. Three explicitly versioned successor GETs return the same DTO.
BEGIN;
SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;
DO $boundary$ BEGIN
 IF to_regnamespace('hotels_read_once_private') IS NOT NULL
 OR NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20260811448200')
 OR EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version ~ '^20260811[0-9]{6}$' AND version>'20260811448200')
 THEN RAISE EXCEPTION 'hotels_114483_boundary_mismatch'; END IF;
END $boundary$;
CREATE SCHEMA hotels_read_once_private AUTHORIZATION postgres;
REVOKE ALL ON SCHEMA hotels_read_once_private FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION hotels_read_once_private.metadata(p_oid oid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS 'SELECT jsonb_build_array(encode(sha256(convert_to(p.prosrc,''UTF8'')),''hex''),
 encode(sha256(convert_to(pg_get_functiondef(p.oid),''UTF8'')),''hex''),
 pg_get_userbyid(p.proowner),p.proacl::text,p.proconfig,p.provolatile,p.prosecdef,
 p.proleakproof,p.proisstrict,p.proretset,l.lanname)
 FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=p_oid';
REVOKE ALL ON FUNCTION hotels_read_once_private.metadata(oid) FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE hotels_read_once_private.certificate(id integer PRIMARY KEY CHECK(id=1),predecessors jsonb NOT NULL,functions jsonb NOT NULL,business_before text NOT NULL);
ALTER TABLE hotels_read_once_private.certificate ENABLE ROW LEVEL SECURITY;
ALTER TABLE hotels_read_once_private.certificate FORCE ROW LEVEL SECURITY;
REVOKE ALL ON hotels_read_once_private.certificate FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION hotels_read_once_private.immutable() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $f$
BEGIN RAISE EXCEPTION 'hotels_114483_certificate_immutable'; END $f$;
REVOKE ALL ON FUNCTION hotels_read_once_private.immutable() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON hotels_read_once_private.certificate FOR EACH STATEMENT EXECUTE FUNCTION hotels_read_once_private.immutable();
