CREATE FUNCTION public.hotel_v2_admin_get_legacy_pricing_promotion_preview_114483(p_hotel_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,auth AS 'BEGIN
 PERFORM public.hotel_v2_h2a_require_admin();
 IF auth.uid() IS NULL THEN RAISE EXCEPTION USING errcode=''42501'',message=''hotels_114483_admin_required''; END IF;
 RETURN hotels_read_once_private.projection_2(p_hotel_id); END;';
