-- Populate the new certificate once; old certificates/receipts are never changed.
ALTER TABLE hotels_read_once_private.certificate DISABLE TRIGGER immutable;
UPDATE hotels_read_once_private.certificate SET functions=(SELECT jsonb_object_agg(p.oid::regprocedure::text,hotels_read_once_private.metadata(p.oid) ORDER BY p.oid::regprocedure::text)
FROM pg_proc p WHERE p.pronamespace='hotels_read_once_private'::regnamespace OR p.oid IN('public.hotel_v2_admin_get_shadow_preparation_state_114483(uuid)'::regprocedure,'public.hotel_v2_admin_get_seven_arches_pricing_activation_114483()'::regprocedure,'public.hotel_v2_admin_get_legacy_pricing_promotion_preview_114483(uuid)'::regprocedure));
ALTER TABLE hotels_read_once_private.certificate ENABLE TRIGGER immutable;
DO $post$ BEGIN
 PERFORM hotels_read_once_private.assert_exact();
 IF hotels_stripe_dto_private.business_hash() IS DISTINCT FROM (SELECT business_before FROM hotels_read_once_private.certificate WHERE id=1)
 OR public.hotel_v2_seven_arches_pricing_activation_current_is_safe() IS NOT TRUE
 OR hotels_shadow_successor_private.state('9b6d99a0-923a-4fbc-be54-c066e856e6ca')->>'status' IS DISTINCT FROM 'SUCCESSOR_ALREADY_COMPLETE'
 OR hotels_lifecycle_private.safe_state()->'feature_flags' IS DISTINCT FROM '{"hotel_rooms_v2_enabled":false,"hotel_external_sync_enabled":true,"hotel_instant_booking_enabled":false,"hotel_stripe_connect_enabled":false}'::jsonb
 OR hotels_lifecycle_private.public_booking_enabled() IS NOT FALSE
 THEN RAISE EXCEPTION 'hotels_114483_postcondition_failed'; END IF;
END $post$;
